class iam_inline_policy_allows_privilege_escalation(Check):
    def execute(self) -> Check_Report_AWS:
        findings = []

        # Iterate over all the IAM inline policies
        for policy in iam_client.policies:
            if policy.type == "Inline":
                report = Check_Report_AWS(self.metadata())
                report.resource_id = f"{policy.entity}/{policy.name}"
                report.resource_arn = policy.arn
                report.region = iam_client.region
                report.resource_tags = policy.tags
                report.status = "PASS"
                report.status_extended = f"Inline Policy {policy.name} attached to {policy.entity} does not allow privilege escalation."

                policies_affected = check_privilege_escalation(policy.document)

                if policies_affected:
                    report.status = "FAIL"
                    report.status_extended = (
                        f"Inline Policy {policy.name} attached to {policy.entity} allows privilege escalation using the following actions: {policies_affected}".rstrip()
                        + "."
                    )

                findings.append(report)
        return findings
